37	/**
38	 * Verifies that `projectId` belongs to `studioId` before any write.
39	 * Returns `{ ok: true }` when the project is found, `{ ok: false, error }` otherwise.
40	 * Mirrors the inline check in `updateProjectStatusAction` (line ~461).
41	 */
42	async function verifyProjectInStudio(
43	  supabase: Awaited<ReturnType<typeof createClient>>,
44	  studioId: string,
45	  projectId: string,
46	): Promise<{ ok: true } | { ok: false; error: string }> {
47	  const { data, error } = await supabase
48	    .from('projects')
49	    .select('id')
50	    .eq('id', projectId)
51	    .eq('studio_id', studioId)
52	    .single()
53	
54	  if (error || !data) {
55	    return { ok: false, error: 'Project not found' }
56	  }
57	  return { ok: true }
58	}
