474	// ─── Status change + activity log ─────────────────────────────────────────────
475	
476	export async function updateProjectStatusAction(
477	  projectId: string,
478	  newStatus: ProjectStatus
479	): Promise<ActionResult<void>> {
480	  const auth = await getAuthenticatedUser()
481	  if (!auth) return { ok: false, error: 'Not authenticated' }
482	  if (!canWrite(auth.role as ReadRole)) return { ok: false, error: 'Insufficient permissions' }
483	
484	  const supabase = await createClient()
485	
486	  const { data: current, error: fetchErr } = await supabase
487	    .from('projects')
488	    .select('status')
489	    .eq('id', projectId)
490	    .eq('studio_id', auth.studioId)
491	    .single()
492	
493	  if (fetchErr || !current) {
494	    return { ok: false, error: 'Project not found' }
495	  }
496	
497	  const prevStatus = current.status
498	
499	  const { error: updateErr } = await supabase
500	    .from('projects')
501	    .update({ status: newStatus, updated_at: new Date().toISOString() })
502	    .eq('id', projectId)
503	    .eq('studio_id', auth.studioId)
504	
505	  if (updateErr) {
506	    logger.error({ updateErr, projectId }, 'updateProjectStatusAction update failed')
507	    return { ok: false, error: 'Failed to update status' }
508	  }
509	
510	  // Append activity log — best-effort (awaited so ordering is deterministic; never 500 on failure)
511	  try {
512	    const { error: logErr } = await supabase
513	      .from('project_activity_log' as 'projects')
514	      .insert({
515	        project_id: projectId,
516	        actor_id: auth.user.id,
517	        event_type: 'status_changed',
518	        details: { prev_status: prevStatus, new_status: newStatus },
519	      } as never)
520	    if (logErr) logger.warn({ logErr, projectId }, 'activity log insert failed — audit gap')
521	  } catch (err) {
522	    logger.warn({ err, projectId }, 'Failed to insert activity log — audit gap')
523	  }
524	
525	  revalidatePath('/projects')
526	  revalidatePath(`/projects/${projectId}`)
527	  return { ok: true, data: undefined }
528	}
